let lastRunTimestamp = flow.get("last_successful_run_timestamp") || '1970-01-01T00:00:00.000Z';


msg.timestamp = lastRunTimestamp;

msg.current_run_timestamp = new Date().toISOString();

return msg;

if (!Array.isArray(msg.payload)) {
    node.error("MSSQL node did not return an array.", msg);
    return null; // Stoppt den Flow hier
}

if (msg.payload.length === 0) {
    node.log("No changes detected since " + msg.timestamp);
    flow.set("last_successful_run_timestamp", msg.current_run_timestamp);
    return null; // Stoppt den Flow hier
}

node.log(`Processing ${msg.payload.length} changed rows...`);

let messagesToSend = [];
let updatedTours = {};

for (const row of msg.payload) {
    const tourName = row.tour_set_name.replace(/\//g, '_');
    const vbeln = row.vbeln;

    // TOUR DATA
    if (!updatedTours[tourName]) {
        const tourTopic = `polipol/8200/mag/mag-mag/tour/${tourName}/sortierer_state`;
        const tourPayload = {
            state_id: row.tour_state_id,
            updated_at: row.tour_update_ts, 
            checked_at: msg.current_run_timestamp 
        };
        messagesToSend.push({
            topic: tourTopic,
            payload: tourPayload,
            qos: 1, 
            retain: true 
        });
        updatedTours[tourName] = true;
    }

    // TA DATA
    const vbelnTopic = `polipol/8200/mag/mag-mag/tour/${tourName}/sortierer_ta/${vbeln}`;
    const vbelnPayload = {
        state: row.vbeln_state,
        updated_at: row.vbeln_update_ts,
        checked_at: msg.current_run_timestamp
    };
    messagesToSend.push({
        topic: vbelnTopic,
        payload: vbelnPayload,
        qos: 1,
        retain: true 
    });
}

// Update timestamp var
flow.set("last_successful_run_timestamp", msg.current_run_timestamp);
node.log(`Successfully processed changes. Next run will check after ${msg.current_run_timestamp}`);


return [messagesToSend];

if (!Array.isArray(msg.payload) || msg.payload.length === 0) {
    // Keine Daten gefunden
    return {
        topic: `polipol/response/vbeln/vbap/${msg.vbeln}`,
        payload: {
            vbeln: msg.vbeln,
            status: "not_found",
            timestamp: new Date().toISOString()
        },
        qos: 1,
        retain: false
    };
}

// Daten gefunden, formatiere Antwort für die Gesamtübersicht
const result = {
    vbeln: msg.vbeln,
    status: "found",
    timestamp: new Date().toISOString(),
    data: msg.payload
};

// Setze das Response-Topic basierend auf den gefundenen Daten
// Wir verwenden das Werk aus dem ersten Eintrag, falls vorhanden
let werk = "unknown";
if (msg.payload.length > 0 && msg.payload[0].zzprwrk) {
    werk = msg.payload[0].zzprwrk;
}

// Speichere diese vbeln in der Liste der zu aktualisierenden Aufträge
let requestedOrders = flow.get("requestedOrders_vbap") || [];
const existingEntry = requestedOrders.find(entry => entry.vbeln === msg.vbeln);
if (!existingEntry) {
    requestedOrders.push({
        vbeln: msg.vbeln,
        timestamp: new Date().toISOString()
    });
    flow.set("requestedOrders_vbap", requestedOrders);
    node.debug(`Neue Verkaufsbelegnummer ${msg.vbeln} zur täglichen Aktualisierung hinzugefügt`);
}

// Erstelle ein Array für alle zu sendenden Nachrichten
const messages = [];

// Hauptnachricht mit allen Positionen
messages.push({
    topic: `polipol/${werk}/order/vbap/vbeln/${msg.vbeln}`,
    payload: result,
    qos: 1,
    retain: true
});

// Einzelne Nachrichten für jede Position
msg.payload.forEach(position => {
    if (position.posnr) {
        const posResult = {
            vbeln: msg.vbeln,
            posnr: position.posnr,
            status: "found",
            timestamp: new Date().toISOString(),
            data: position
        };

        messages.push({
            topic: `polipol/${werk}/order/vbap/vbeln/${msg.vbeln}/${position.posnr}`,
            payload: posResult,
            qos: 1,
            retain: true
        });
    }
});

return [messages];

let vbeln;

if (msg.payload && typeof msg.payload === 'object') {
    vbeln = msg.payload.vbeln;
} else if (typeof msg.payload === 'string') {
    try {
        const data = JSON.parse(msg.payload);
