            status: "not_found",
            timestamp: new Date().toISOString()
        },
        qos: 1,
        retain: false
    };
}

// Daten gefunden, formatiere Antwort
const result = {
    aufnr: msg.aufnr,
    status: "found",
    timestamp: new Date().toISOString(),
    data: msg.payload
};

// Setze das Response-Topic basierend auf den gefundenen Daten
const entry = msg.payload[0];
msg.responseTopic = `polipol/${entry.dwerk}/order/afpo/vbeln/${entry.vbeln}/aufnr/${entry.aufnr}`;


// Speichere diese aufnr in der Liste der zu aktualisierenden Aufträge
let requestedOrders = flow.get("requestedAufnr_afpo") || [];
const existingEntry = requestedOrders.find(entry => entry.aufnr === msg.aufnr);
if (!existingEntry) {
    requestedOrders.push({
        aufnr: msg.aufnr,
        timestamp: new Date().toISOString()
    });
    flow.set("requestedAufnr_afpo", requestedOrders);
    node.debug(`Neue Auftragsnummer ${msg.aufnr} zur täglichen Aktualisierung hinzugefügt`);
}

return {
    topic: msg.responseTopic,
    payload: result,
    qos: 1,
    retain: true
};

// Save file in flow context
if (msg.payload && msg.payload.length > 0) {
    flow.set('uploadedFile', msg.payload);
    flow.set('fileName', msg.file.name || 'uploaded.xlsx');

    // Validate file type
    const fileName = msg.file.name || '';
    const validExtensions = ['.xlsx', '.xls', '.XLSX'];
    const isValid = validExtensions.some(ext => fileName.toLowerCase().endsWith(ext));

    if (isValid) {
        msg.payload = `✅ Plik "${fileName}" został załadowany`;
        msg.topic = 'file_ready';
        return [msg, null];
    } else {
        msg.payload = `❌ Nieprawidłowy typ pliku. Dozwolone są tylko pliki .xlsx i .xls.`;
        msg.topic = 'file_error';
        return [null, msg];
    }
} else {
    msg.payload = 'Nie wybrano pliku';
    msg.topic = 'no_file';
    return [null, msg];
}

// Get stored file
const fileData = flow.get('uploadedFile');
const fileName = flow.get('fileName');

if (!fileData) {
    msg.payload = '❌ Brak pliku do przetworzenia';
    msg.topic = 'error';
    return [null, msg];
}

msg.payload = fileData;
msg.filename = fileName;
msg.topic = 'process_file';

const statusMsg = {
    payload: '🔄 Przetwarzanie rozpoczęte...',
    topic: 'processing'
};
node.log("File uploaded");
return [msg, statusMsg];

try {
    const data = msg.payload;
    const messages = [];
    const tableData = [];
    let processedCount = 0;

    if (!Array.isArray(data) || data.length < 2) {
        const errorMsg = {
            payload: '❌ Brak poprawnych danych w pliku Excel',
            topic: 'error'
        };
        return [null, null, null, errorMsg];
    }

    const headers = data[0];
    const rows = data.slice(1);
    const processedRows = rows.map(row =>
        headers.reduce((obj, key, i) => {
            obj[key] = row[i] !== undefined ? row[i] : null;
            return obj;
        }, {})
    );

    processedRows.forEach((row, index) => {
        try {
            const matBereitstellungsDatum = row['Mat.Bereitst.Datum'] || row['MatBereitstellungsDatum']|| row['Mat.Bereitst.Datum'] || row['Datum'] || row['Data dostępn. mat.'];
            let route = row['Route'] || row['Trasa'];
            if (route === 'SHOP') {
                route = -1;
            }
            const verkaufsbeleg = row['Verkaufsbeleg'] || row['VBELN'] || row['Dokument sprzedaży'];
            const hauptstoff = row['Hauptstoff'] || row['Tkanina główna'] ;
            const absatzstoff = row['Absatzstoff'] || row['Tkanina druga'];
            let garniturId = row['Garnitur- ID'] || "";
            let parts = garniturId.split('/');
            const werks = parts[parts.length - 1];
            if (!matBereitstellungsDatum || !route || !verkaufsbeleg) {
                node.warn(`Wiersz ${index + 1}: Brak wymaganych danych`);
                return;
            }
            let formattedDate;
            if (matBereitstellungsDatum instanceof Date) {
                formattedDate = matBereitstellungsDatum.toISOString().split('T')[0];
            } else if (typeof matBereitstellungsDatum === 'string') {
                const dateStr = matBereitstellungsDatum.trim();
                if (dateStr.includes('.')) {
                    const parts = dateStr.split('.');
                    if (parts.length === 3) {
                        formattedDate = `${parts[2]}-${parts[1].padStart(2, '0')}-${parts[0].padStart(2, '0')}`;
                    }
                } else {
                    formattedDate = dateStr;
                }
            }
            const tour_id = `${route}_${formattedDate.replace(/-/g, '')}_${werks}`;
            const topic = `polipol/${werks}/order/zprod/tour_id/${tour_id}/vbeln/${verkaufsbeleg}`;
            const payload = {
                tour_id: tour_id,
                vbeln: verkaufsbeleg,
                route: route,
                mat_bereitstellungs_datum: formattedDate,
                hauptstoff: hauptstoff || null,
                absatzstoff: absatzstoff || null,
                bestaetigte_menge: row['Bestätigte Menge'] || row['BestaetigteMenge'] || row['Ilość potwierdzona'],
                lieferpriorität: row['Lieferpriorität'] || row['Lieferprioritaet'] || row['Priorytet dostawy'],
                position: row['Position'] || row['Poz. dok. sprzedaży'],
                material: row['Material'] || row['Materiał'],
                materialkurztext: row['Materialkurztext'] || row['Opis materiału'],
                bezeichnung: row['Bezeichnung'] || row['Nazwa'],
                timestamp: new Date().toISOString(),
                source_file: msg.filename
            };
            messages.push({
                topic: topic,
                payload: payload,
                qos: 1,
                retain: true
            });
            tableData.push({
                vbeln: verkaufsbeleg,
                tour_id: tour_id,
                hauptstoff: hauptstoff || '-'
            });
            processedCount++;
            node.log("neuer Beleg hinzugefügt");
        } catch (rowError) {
            node.error(`Wiersz ${index + 1}: ${rowError.message}`);
        }
    });
    if (messages.length === 0) {
        const errorMsg = {
            payload: '❌ Nie przetworzono żadnych poprawnych rekordów',
            topic: 'error'
        };
        return [null, null, null, errorMsg];
    }
    const tableMsg = {
        payload: tableData,
        topic: 'table_update'
    };
    const counterMsg = {
        payload: `${processedCount} z ${processedRows.length} rekordów`,
        topic: 'counter_update'
    };
    const statusMsg = {
        payload: `✅ ${processedCount} rekordów poprawnie przetworzono`,
        topic: 'success'
    };
    const notificationMsg = {
        payload: `🚀 ${processedCount} rekordów ZPROD zostało pomyślnie przesłanych!`,
        topic: 'success'
    };
    return [messages, tableMsg, counterMsg, statusMsg, notificationMsg];
} catch (error) {
    node.error(`Błąd przetwarzania: ${error.message}`);
    const errorMsg = {
        payload: `❌ Błąd przetwarzania: ${error.message}`,
        topic: 'error'
    };
    return [null, null, null, errorMsg, errorMsg];
}

// Originaldaten sichern
msg._original = RED.util.cloneMessage(msg.payload);

// Hilfsfunktion für 18-stellige Materialnummer
function padMatnr(num) {
    if (!num) return null;
    num = String(num).replace(/^0+/, ''); // führende Nullen entfernen
    return num.padStart(18, '0');
}

const hauptstoff = padMatnr(msg.payload.hauptstoff);
const absatzstoff = padMatnr(msg.payload.absatzstoff);

msg.hauptstoff = hauptstoff;
msg.absatzstoff = absatzstoff;

return [msg, msg, msg];

if (!msg.hauptstoff) return null;
msg.query = `SELECT maktx, 'hauptstoff' as type FROM ods.st_makt WHERE matnr = '${msg.hauptstoff}' AND spras = 'D' LIMIT 1;`;
return msg;

if (!msg.absatzstoff) return null;
msg.query = `SELECT maktx, 'absatzstoff' as type FROM ods.st_makt WHERE matnr = '${msg.absatzstoff}' AND spras = 'D' LIMIT 1;`;
return msg;

if (msg.payload.length === 0) {
    return null;
}
let payload = msg._original;

if (msg.hauptstoff_name) payload.hauptstoff = msg.hauptstoff_name;
if (msg.absatzstoff_name) payload.absatzstoff = msg.absatzstoff_name;

msg.payload = payload;
if (msg.hauptstoff && !msg.hauptstoff_name) return null;
if (msg.absatzstoff && !msg.absatzstoff_name) return null;
return msg;

if (Array.isArray(msg.payload)) {
    msg.payload.forEach(obj => {
        if (obj.type === "hauptstoff" && obj.maktx) {
            msg.hauptstoff_name = obj.maktx;
        }
        if (obj.type === "absatzstoff" && obj.maktx) {
            msg.absatzstoff_name = obj.maktx;
        }
    });
}
return msg;

try {
    var payload = msg.payload;

    // tour_id aus dem Payload extrahieren
    var tour_id = payload.tour_id;
    var werks = payload.werks || 8200;

    if (!tour_id) {
        throw new Error('tour_id fehlt im Payload');
    }

    // Split tour_id in tour_number und tour_date
    var parts = tour_id.split('_');
    if (parts.length !== 3) {
        throw new Error('tour_id Format ungültig, erwartet tour_number_tour_date_plant');
    }

    var tour_number = parts[0];
    var tour_date = parts[1];

    var schema = 'digital_buffer_szw';
    var table = 'tour_ids';

    msg.sql = {
        schema: schema,
        table: table,
        columns: ['tour_id', 'tour_date', 'tour_number', 'werks'],
        values: [tour_id, tour_date, tour_number, werks]
    };

    var columns = msg.sql.columns.join(', ');
    var values = msg.sql.values;
    var sqlValues = values.map(value => {
        if (value === null || value === undefined || value === '') {
            return 'NULL';
        } else if (typeof value === 'string') {
            return `'${value}'`;
        } else if (typeof value === 'boolean') {
            return value ? 'TRUE' : 'FALSE';
        } else {
            return value;
        }
    }).join(', ');

    var query = `
        INSERT INTO ${schema}.${table} (${columns}) VALUES (${sqlValues})
        ON CONFLICT (tour_id) 
        DO UPDATE SET 
            tour_date = EXCLUDED.tour_date,
            tour_number = EXCLUDED.tour_number,
            werks = EXCLUDED.werks;`;

    msg.query = query;

    return msg;

} catch (error) {
    node.error(`Fehler beim Verarbeiten der tour_id: ${error.message}`);
    msg.error = error.message;
    return msg;
}

const error_msg = {
    payload: 'plik za duży',
    topic: 'failure'
}
return error_msg;

const raw = flow.get('nummern_input') || '';

// Podziel linie, przytnij, usuń puste
const lines = raw.split(/[\r\n]+/)
    .map(l => l.trim())
    .filter(l => l.length > 0);

if (lines.length === 0) {
    return [null, { payload: '❌ Nie wprowadzono żadnych numerów' }];
}

// Usuń duplikaty
const unique = [...new Set(lines)];
const duplicates = lines.length - unique.length;

// Utwórz wiadomości MQTT
const messages = unique.map(nummer => ({
    topic: 'polipol/request/aufnr/afpo/manual',
    payload: nummer,
    qos: 1,
    retain: false
}));

// Komunikat statusu
let statusText = `🔄 Wysyłanie ${unique.length} numer(ów)...`;
if (duplicates > 0) {
    statusText += ` (usunięto ${duplicates} duplikat(ów))`;
}
const statusMsg = { payload: statusText };

flow.set('tour_ta_total', unique.length);
flow.set('tour_ta_sent', 0);

return [messages, statusMsg];

let sent = (flow.get('tour_ta_sent') || 0) + 1;
const total = flow.get('tour_ta_total') || 0;
flow.set('tour_ta_sent', sent);

const counterMsg = {
    payload: `${sent} / ${total}`
};

if (sent >= total) {
    const doneMsg = {
        payload: `✅ Wszystkie ${total} żądania zostały pomyślnie wysłane!`
    };
    return [counterMsg, doneMsg];
}

return [counterMsg, null];
